    // Retrieve the conversion pattern from the event's logger
    String conversionPattern = event.getLogger().getConversionPattern();

    // Parse the conversion pattern into a format string and an argument array
    String formatString = conversionPattern.substring(0, conversionPattern.indexOf("{"));
    String[] arguments = conversionPattern.substring(conversionPattern.indexOf("{") + 1, conversionPattern.indexOf("}")).split(",");

    // Replace the argument placeholders with the actual argument values
    for (int i = 0; i < arguments.length; i++) {
        String argument = arguments[i];
        if (argument.equals("{")) {
            continue;
        }
        if (argument.equals("}")) {
            break;
        }
        String value = event.getProperty(argument);
        if (value == null) {
            value = "";
        }
        formatString = formatString.replaceFirst("\\{}", value);
    }

    // Return the formatted string
    return formatString;
}

