public void generateGraph(Graph<V, E> target, Map<String, V> resultMap) {
    // create a new empty graph with the same vertex and edge types as the input graph
    Graph<V, E> graph = new Graph<>(target.getVertexType(), target.getEdgeType());

    // add all vertices to the graph
    for (V vertex : resultMap.values()) {
        graph.addVertex(vertex);
    }

    // add all edges to the graph
    for (E edge : target.getEdges()) {
        V sourceVertex = resultMap.get(edge.getSource());
        V targetVertex = resultMap.get(edge.getTarget());
        graph.addEdge(sourceVertex, targetVertex, edge);
    }

    // set the graph as the target graph
    target.setVertices(graph.getVertices());
    target.setEdges(graph.getEdges());
}

@Override
public void generateGraph(Graph<V, E> target, Map<String, V> resultMap) {
    // Check if the graph is empty
    if (target.isEmpty()) {
        throw new IllegalArgumentException("The graph cannot be empty");
    }
    // Check if the result map is empty
    if (resultMap.isEmpty()) {
        throw new IllegalArgumentException("The result map cannot be empty");
    }
    // Get the number of vertices in the graph
    int numVertices = target.getNumVertices();
    // Get the number of edges in the graph
    int numEdges = target.getNumEdges();
    // Create a map to store the list of vertices in the first partite set
    Map<String, List<V>> partiteSet1 = new HashMap<>();
    // Create a map to store the list of vertices in the second partite set
    Map<String, List<V>> partiteSet2 = new HashMap<>();
    // Iterate over the vertices in the graph
    for (V vertex : target.getVertices()) {
        // Check if the vertex is in the first partite set
        if (partiteSet1.containsKey(vertex)) {
            // If the vertex is in the first partite set, add it to the map
            partiteSet1.get(vertex).add(vertex);
        } else {
            // If the vertex is not in the first partite set, add it to the second partite set
            partiteSet2.get(vertex).add(vertex);
        }
    }
    // Iterate over the edges in the graph
    for (E edge : target.getEdges()) {
        // Check if the edge is incident to a vertex in the first partite set
        if (partiteSet1.containsKey(edge.getStartVertex()) && partiteSet2.containsKey(edge.getEndVertex())) {
            // If the edge is incident to a vertex in the first partite set, add it to the second partite set
            partiteSet2.get(edge.getEndVertex()).add(edge);
        } else if (partiteSet1.containsKey(edge.getEndVertex()) && partiteSet2.containsKey(edge.getStartVertex())) {
            // If the edge is incident to a vertex in the second partite set, add it to the first partite set
            partiteSet1.get(edge.getStartVertex()).add(edge);
        }
    }
    // Return the list of vertices in the first partite set
    return partiteSet1.get(partiteSet1.keySet().iterator().next());
}

public void generateGraph(Graph<V,E> target, Map<String,V> resultMap) {
    int n = target.numV();
    int m = target.numE();
    for (int i = 0; i < n; i++) {
        Vertex<V> u = target.vertexAt(i);
        for (int j = 0; j < m; j++) {
            Vertex<V> v = target.vertexAt(j);
            target.addEdge(u, v);
        }
    }
    for (int i = 0; i < n; i++) {
        Vertex<V> u = target.vertexAt(i);
        for (int j = 0; j < m; j++) {
            Vertex<V> v = target.vertexAt(j);
            if (!target.hasEdge(u, v)) {
                target.addEdge(u, v);
            }
        }
    }
}

