public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    int size = ProtobufCodedOutputStream.computeDelimitedSize(schema, message, buffer);
    ProtobufCodedOutputStream codedOut = ProtobufCodedOutputStream.newInstance(out);
    codedOut.writeRawVarint32(size);
    schema.writeTo(codedOut, message);
    codedOut.flush();
    return size;
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    /*
     * 1. Get the encoded size of the message using the schema.
     * 2. Write the encoded size to the output stream.
     * 3. Write the message to the output stream.
     * 4. Flush the buffer.
     * 5. Return the size of the message.
     */
    int size = schema.getSerializedSize(message);

    out.write(Ints.toByteArray(size));
    schema.writeTo(message, buffer.serializeAndRecycle(out));
    buffer.flush();

    return size;
}

