public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    // Check if the genericType is actually parameterized
    if (!(genericType instanceof ParameterizedType)) {
        return null;
    }

    // Get the type arguments of the parameterized type
    Type[] typeArguments = ((ParameterizedType) genericType).getActualTypeArguments();

    // Check if the type arguments are not empty
    if (typeArguments.length == 0) {
        return null;
    }

    // Get the type variables of the target type
    TypeVariable<?>[] typeVariables = targetType.getTypeParameters();

    // Create a map of type variables to type arguments
    Map<TypeVariable<?>, Type> typeVariableMap = new HashMap<>();
    for (int i = 0; i < typeArguments.length; i++) {
        typeVariableMap.put(typeVariables[i], typeArguments[i]);
    }

    // Resolve the type arguments based on the type variables
    Class<?>[] resolvedTypes = new Class<?>[typeArguments.length];
    for (int i = 0; i < typeArguments.length; i++) {
        Type typeArgument = typeArguments[i];
        if (typeArgument instanceof ParameterizedType) {
            resolvedTypes[i] = (Class<?>) ((ParameterizedType) typeArgument).getRawType();
        } else if (typeArgument instanceof TypeVariable) {
            resolvedTypes[i] = typeVariableMap.get(typeArgument);
        } else {
            resolvedTypes[i] = (Class<?>) typeArgument;
        }
    }

    return resolvedTypes;
}

