public static int computeUTF8Size(CharSequence str, int index, int len) {
    byte[] utf8Array = new byte[len];
    for (int i = 0; i < len; i++) {
        int c = str.charAt(index + i);
        if (c < 0x0080) {
            utf8Array[i] = (byte) c;
        } else if (c < 0x0800) {
            utf8Array[i] = (byte) (0xc0 | c >> 6);
            utf8Array[i + 1] = (byte) (0x80 | c & 0x3f);
        } else {
            utf8Array[i] = (byte) (0xe0 | c >> 12);
            utf8Array[i + 1] = (byte) (0x80 | (c >> 6) & 0x3f);
            utf8Array[i + 2] = (byte) (0x80 | c & 0x3f);
        }
    }
    return utf8Array.length;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    // Step 1: Compute the byte length of the UTF-8 string
    int byteCount = 0;
    for (int i = index; i < index + len; i++) {
        int codePoint = str.codePointAt(i);
        byteCount += codePoint < 0x80 ? 1 : codePoint < 0x800 ? 2 : 3;
    }

    // Step 2: Add the null terminator byte
    byteCount++;

    return byteCount;
}

