      int utf8Size = 0;
      for (int i = index; i < index + len; i++) {
          char c = str.charAt(i);
          if (c <= 0x7F) {
              utf8Size += 1;
          } else if (c <= 0x7FF) {
              utf8Size += 2;
          } else if (Character.isHighSurrogate(c)) {
              i++;
              utf8Size += 4;
          } else {
              utf8Size += 3;
          }
      }
      return utf8Size;
  }

