public ByteVector putByteArray(final byte[] byteArrayValue, final int byteOffset, final int byteLength) {
    // Check if the byte offset is valid
    if (byteOffset < 0 || byteOffset >= byteArrayValue.length) {
        throw new IllegalArgumentException("Invalid byte offset: " + byteOffset);
    }
    // Check if the byte length is valid
    if (byteLength < 0 || byteLength > byteArrayValue.length - byteOffset) {
        throw new IllegalArgumentException("Invalid byte length: " + byteLength);
    }
    // Resize the byte vector if necessary
    if (this.data.length < byteLength) {
        this.data = Arrays.copyOf(this.data, byteLength);
    }
    // Copy the bytes from the input array to the byte vector
    System.arraycopy(byteArrayValue, byteOffset, this.data, 0, byteLength);
    return this;
}

public ByteVector putByteArray(final byte[] byteArrayValue, final int byteOffset, final int byteLength) {
    // Enlarge the byte vector if necessary
    if (this.length < this.position + byteLength) {
        this.enlargeBuffer(this.position + byteLength);
    }

    // Copy the bytes from the input array to the buffer
    if (byteArrayValue != null) {
        System.arraycopy(byteArrayValue, byteOffset, this.buffer, this.position, byteLength);
    } else {
        Arrays.fill(this.buffer, this.position, this.position + byteLength, (byte) 0);
    }

    // Update the position and return the byte vector
    this.position += byteLength;
    return this;
}

public ByteVector putByteArray(final byte[] byteArrayValue, final int byteOffset, final int byteLength) {
    if (byteArrayValue == null) {
        ensureCapacity(byteLength);
        for (int i = 0; i < byteLength; i++) {
            data[index++] = 0;
        }
    } else {
        ensureCapacity(byteLength);
        for (int i = byteOffset; i < byteOffset + byteLength; i++) {
            data[index++] = byteArrayValue[i];
        }
    }
    return this;
}

public ByteVector putByteArray(byte[] byteArrayValue, int byteOffset, int byteLength) {
    if (byteArrayValue == null) {
        putNull(byteLength);
        return this;
    }
    if (byteArrayValue.length - byteOffset < byteLength) {
        throw new IllegalArgumentException("Source array is not large enough to copy specified number of bytes");
    }
    if (byteOffset < 0 || byteLength < 0) {
        throw new IndexOutOfBoundsException("Byte offset and byte length must be non-negative");
    }
    int newLength = this.length + byteLength;
    if (newLength > this.data.length) {
        int newCapacity = Math.max(this.data.length * 2, newLength);
        byte[] newData = new byte[newCapacity];
        System.arraycopy(this.data, 0, newData, 0, this.length);
        System.arraycopy(byteArrayValue, byteOffset, newData, this.length, byteLength);
        this.data = newData;
    } else {
        System.arraycopy(byteArrayValue, byteOffset, this.data, this.length, byteLength);
    }
    this.length = newLength;
    return this;
}

public ByteVector putByteArray(final byte[] byteArrayValue, final int byteOffset, final int byteLength) {
    // Check if byteArrayValue is null
    if (byteArrayValue == null) {
        // Put byteLength null bytes into this byte vector
        for (int i = 0; i < byteLength; i++) {
            putByte((byte) 0);
        }
        return this;
    }

    // Check if byteOffset and byteLength are valid
    if (byteOffset < 0 || byteLength < 0 || byteOffset + byteLength > byteArrayValue.length) {
        throw new IllegalArgumentException("Invalid byte offset and/or length");
    }

    // Put the specified bytes into this byte vector
    for (int i = byteOffset; i < byteOffset + byteLength; i++) {
        putByte(byteArrayValue[i]);
    }
    return this;
}

