public static LinkedBuffer writeUTF8(final CharSequence str,final WriteSession session,final LinkedBuffer lb){
    if(str == null || str.length() == 0){
        return lb;
    }
    //UTF-8 encoding
    char[] buffer = new char[str.length()];
    for(int i = 0; i < str.length(); i++){
        char c = str.charAt(i);
        if(c > 127){
            int codePoint = Character.codePointAt(str, i);
            int n = Character.writeUTF8(codePoint, buffer, i);
            i += n - 1;
        }else{
            buffer[i] = c;
        }
    }
    //write to LinkedBuffer
    for(int i = 0; i < buffer.length; i++){
        lb.writeByte((byte)buffer[i]);
    }
    return lb;
}

public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    final LinkedBuffer result = lb;
    for (int i = 0; i < str.length(); i++) {
        final int codePoint = str.codePointAt(i);
        if (codePoint <= 0x7F) {
            result.writeByte((byte) codePoint);
        } else if (codePoint <= 0x7FF) {
            result.writeByte((byte) (0xC0 | (codePoint >> 6)));
            result.writeByte((byte) (0x80 | (codePoint & 0x3F)));
        } else if (codePoint <= 0xFFFF) {
            result.writeByte((byte) (0xE0 | (codePoint >> 12)));
            result.writeByte((byte) (0x80 | ((codePoint >> 6) & 0x3F)));
            result.writeByte((byte) (0x80 | (codePoint & 0x3F)));
        } else {
            result.writeByte((byte) (0xF0 | (codePoint >> 18)));
            result.writeByte((byte) (0x80 | ((codePoint >> 12) & 0x3F)));
            result.writeByte((byte) (0x80 | ((codePoint >> 6) & 0x3F)));
            result.writeByte((byte) (0x80 | (codePoint & 0x3F)));
        }
    }
    return result;
}

