public static String findAndSubst(String key, Properties props) {
  // Search for the value corresponding to the given key in the properties
  String value = props.getProperty(key);

  // If no value is found, return null
  if (value == null) {
    return null;
  }

  // Perform variable substitution on the found value
  Pattern pattern = Pattern.compile("\\{\\$([a-zA-Z0-9_]+)\\}");
  Matcher matcher = pattern.matcher(value);

  while (matcher.find()) {
    String variableName = matcher.group(1);
    String variableValue = props.getProperty(variableName);

    if (variableValue == null) {
      throw new IllegalArgumentException("Undefined variable: " + variableName);
    }

    value = value.replaceAll("\\{\\$" + variableName + "\\}", variableValue);
  }

  return value;
}

