public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    List<PathSegmentImpl> pathSegments = new ArrayList<>();
    String path = u.getPath();
    while (path.startsWith("/")) {
        int nextSlashIndex = path.indexOf("/", 1);
        String pathSegment = path.substring(1, nextSlashIndex);
        if (decode) {
            pathSegment = URLDecoder.decode(pathSegment, StandardCharsets.UTF_8);
        }
        pathSegments.add(new PathSegmentImpl(pathSegment));
        path = path.substring(nextSlashIndex);
    }
    return pathSegments;
}

public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
  String path = u.getPath();
  String[] segments = path.split("/");
  List<PathSegmentImpl> pathSegments = new ArrayList<>();
  for (String segment : segments) {
    if (decode) {
      segment = UriUtils.decode(segment, StandardCharsets.UTF_8.name());
    }
    pathSegments.add(new PathSegmentImpl(segment));
  }
  return pathSegments;
}

public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    List<PathSegmentImpl> pathSegments = new ArrayList<>();
    for (String segment : u.getRawPath().split("/")) {
        if (segment.isEmpty()) {
            continue;
        }
        if (decode) {
            segment = URLDecoder.decode(segment, "UTF-8");
        }
        pathSegments.add(new PathSegmentImpl(segment, decode));
    }
    return pathSegments;
}

public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    // Initialize an empty list of path segments
    List<PathSegmentImpl> pathSegments = new ArrayList<PathSegmentImpl>();

    // Get the raw path component from the URI
    String rawPath = u.getRawPath();

    // Split the raw path component into individual segments
    String[] segments = rawPath.split("/");

    // Iterate over the segments and create a path segment object for each one
    for (String segment : segments) {
        if (!segment.isEmpty()) {
            pathSegments.add(new PathSegmentImpl(decode ? URLDecoder.decode(segment, "UTF-8") : segment));
        }
    }

    return pathSegments;
}

public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
   List<PathSegmentImpl> segments = new ArrayList<>();
   String path = u.getPath();
   if (path.isEmpty()) {
      return segments;
   }
   if (path.startsWith("/")) {
      path = path.substring(1);
   }
   while (path.length() > 0) {
      int i = path.indexOf("/");
      String segment = i > 0 ? path.substring(0, i) : path;
      path = i > 0 ? path.substring(i + 1) : "";
      if (decode) {
         segment = URLDecoder.decode(segment, "UTF-8");
      }
      segments.add(new PathSegmentImpl(segment));
   }
   return segments;
}

