public long readRawVarint64() throws IOException {
        long result = 0;
        int shift = 0;
        while (true) {
            byte b = readByte();
            result |= (long)(b & 0x7F) << shift;
            if ((b & 0x80) != 0) {
                shift += 7;
            } else {
                break;
            }
        }
        return result;
    }

public long readRawVarint64() throws IOException {
    long result = 0;
    int offset = 0;
    while (offset < 64) {
        byte b = readByte();
        result |= (long)(b & 0x7F) << offset;
        if ((b & 0x80) == 0) {
            break;
        }
        offset += 7;
    }
    return result;
}

public static long readRawVarint64(InputStream stream) throws IOException {
    long result = 0;
    for (int shift = 0; shift < 64; shift += 7) {
        long b = stream.read();
        if (b == -1) {
            throw new EOFException("Unexpected end of stream while reading varint.");
        }
        result |= (b & 0x7FL) << shift;
        if ((b & 0x80) == 0) {
            return result;
        }
    }
    throw new IOException("Malformed varint.");
}

