private void pop(final String descriptor){
    val frameStack = getGraph().getOutputFrameStack();
    val types = Type.getMethodType(descriptor).getArgumentTypes();
    for (val type : types) {
        if (frameStack.peek() instanceof AbstractType) {
            frameStack.pop();
        }
    }
}

private void pop(final String descriptor) {
    int numTypesToPop = getNumTypesToPop(descriptor);
    for (int i = 0; i < numTypesToPop; i++) {
        outputStack.pop();
    }
}

private int getNumTypesToPop(String descriptor) {
    // Count the number of types in the descriptor.
    int numTypes = 0;
    for (int i = 0; i < descriptor.length(); i++) {
        if (descriptor.charAt(i) == ')') {
            numTypes++;
        }
    }
    return numTypes;
}

private void pop(final String descriptor) {
    int numTypes = descriptor.length();
    for (int i = 0; i < numTypes; i++) {
        Type type = Type.getType(descriptor.charAt(i));
        if (type == Type.METHOD) {
            for (int j = 0; j < type.getArgumentTypes().length; j++) {
                pop(type.getArgumentTypes()[j].getDescriptor());
            }
        } else {
            pop(type.getDescriptor());
        }
    }
}

private void pop(final String descriptor) {
    int argumentCount = descriptor.split("\\").length;
    for (int i = 0; i < argumentCount; i++) {
        pop();
    }
}

private void pop(String descriptor) {
    Type[] types = Type.getArgumentTypes(descriptor);
    for (Type type : types) {
        switch (type.getSort()) {
            case Type.OBJECT:
                Object output = stack.pop();
                if (!output.getClass().isAssignableFrom(type.getClassName())) {
                    throw new RuntimeException("Unexpected type on stack: expected " + type.getClassName() + " but was " + output.getClass().getName());
                }
                break;
            case Type.ARRAY:
                Object output = stack.pop();
                if (!(output instanceof List)) {
                    throw new RuntimeException("Unexpected type on stack: expected List but was " + output.getClass().getName());
                }
                break;
            case Type.METHOD:
                Method method = (Method) stack.pop();
                if (!method.getReturnType().isAssignableFrom(type.getReturnType())) {
                    throw new RuntimeException("Unexpected type on stack: expected " + type.getReturnType() + " but was " + method.getReturnType().getName());
                }
                break;
            default:
                throw new RuntimeException("Unsupported type: " + type.getSort());
        }
    }
}

public void write(byte b[], int off, int len) throws IOException {
    if (b == null) {
        throw new NullPointerException();
    }
    if (off < 0 || off > b.length - len) {
        throw new IndexOutOfBoundsException();
    }
    if (len < 0) {
        throw new IndexOutOfBoundsException();
    }
    for (int i = 0; i < len; i++) {
        write(b[off + i]);
    }
}

@Override
public void write(byte[] b, int off, int len) throws IOException {
    if (b == null || off < 0 || len < 0 || off >= b.length) {
        throw new RuntimeException("Invalid input parameters");
    }

    if (len == 0) {
        return;
    }

    int bytesWritten = 0;
    while (bytesWritten < len) {
        int byteToWrite = b[off + bytesWritten];
        if (byteToWrite < 0) {
            byteToWrite += 256;
        }
        this.write(byteToWrite);
        bytesWritten++;
    }
}

public void write(final byte b[], final int off, final int len) throws IOException {
    if (b == null) {
        throw new NullPointerException("Data to write cannot be null");
    }
    if (off < 0 || off >= b.length) {
        throw new IndexOutOfBoundsException("Offset out of bounds");
    }
    if (len < 0 || len > b.length - off) {
        throw new IllegalArgumentException("Invalid length");
    }
    for (int i = 0; i < len; i++) {
        write(b[off + i]);
    }
}

