        throw new IllegalArgumentException("Vertices and edge cannot be null");
    }
    if (sourceVertex.equals(targetVertex)) {
        throw new IllegalArgumentException("Source and target vertex cannot be the same");
    }
    if (edges.containsKey(sourceVertex)) {
        edges.get(sourceVertex).put(targetVertex, e);
    } else {
        HashMap<V, E> edgeMap = new HashMap<>();
        edgeMap.put(targetVertex, e);
        edges.put(sourceVertex, edgeMap);
    }
}

