public static Pair<Box2D, Box2D> splitAlongXAxis(Box2D box) {
  // Calculate the midpoint of the box along the x-axis
  double midpointX = (box.getMinX() + box.getMaxX()) / 2;

  // Create two new boxes, one with the lower half of the original box
  // and one with the upper half
  Box2D lowerHalf = new Box2D(box.getMinX(), box.getMinY(), midpointX, box.getMaxY());
  Box2D upperHalf = new Box2D(midpointX, box.getMinY(), box.getMaxX(), box.getMaxY());

  return Pair.of(lowerHalf, upperHalf);
}

public static Pair<Box2D, Box2D> splitAlongXAxis(Box2D box) {
    double x = box.getX();
    double y = box.getY();
    double width = box.getWidth();
    double height = box.getHeight();

    double midX = x + (width / 2.0);
    Box2D box1 = new Box2D(x, y, midX - x, height);
    Box2D box2 = new Box2D(midX, y, x + width - midX, height);

    return new Pair<>(box1, box2);
}

public static Pair<Box2D, Box2D> splitAlongXAxis(Box2D box) {
    double midX = (box.x + box.width) / 2;
    Box2D box1 = new Box2D(box.x, box.y, midX - box.x, box.height);
    Box2D box2 = new Box2D(midX, box.y, box.width - (midX - box.x), box.height);
    return new Pair<>(box1, box2);
}

public static Pair<Box2D, Box2D> splitAlongXAxis(Box2D box) {
    double centerX = box.getCenter().getX();
    double width = box.getWidth();
    double height = box.getHeight();
    Box2D box1 = new Box2D(centerX - width / 2, centerX, height);
    Box2D box2 = new Box2D(centerX, centerX + width / 2, height);
    return new Pair<>(box1, box2);
}

public static Pair<Box2D,Box2D> splitAlongXAxis(Box2D box) {
  Point2D center = box.getCenter();
  double width = box.getWidth();
  double height = box.getHeight();

  // Calculate the split point
  double splitX = center.getX() - (width / 2);

  // Split the box into two smaller boxes
  Box2D leftBox = new Box2D(splitX, center.getY(), width / 2, height);
  Box2D rightBox = new Box2D(splitX + (width / 2), center.getY(), width / 2, height);

  return new Pair<>(leftBox, rightBox);
}

