  }
  return desiredCapacity;
}

public static int nextPrimeCloseTo(int desiredCapacity){
  int prime = 0;
  int distance = Integer.MAX_VALUE;
  for (int i = desiredCapacity - desiredCapacity / 11; i <= desiredCapacity + desiredCapacity / 11; i++) {
    if (isPrime(i)) {
      int dist = Math.abs(i - desiredCapacity);
      if (dist < distance) {
        distance = dist;
        prime = i;
      }
    }
  }
  return prime;
}

