public static int nextPrime(int desiredCapacity) {
    desiredCapacity = Math.max(5, desiredCapacity);
    if (desiredCapacity <= 5 || desiredCapacity % 2 == 0 || desiredCapacity % 3 == 0 || desiredCapacity % 5 == 0 || desiredCapacity % 7 == 0 || desiredCapacity % 11 == 0) {
        desiredCapacity += 2;
    }
    int prime = 0;
    do {
        int i = (int)Math.sqrt(desiredCapacity) + 1;
        for (int j = 2; j < i; j++) {
            if (Math.pow(j, 2) % desiredCapacity == 0) {
                desiredCapacity += 2;
                break;
            }
        }
        if (desiredCapacity == i) {
            prime = desiredCapacity;
        }
    } while (prime == 0);
    return prime;
}

