    if (desiredCapacity < 2) {
        return 2;
    }
    // Find the next prime number greater than or equal to the desired capacity
    while (!isPrime(desiredCapacity)) {
        desiredCapacity++;
    }
    // If the desired capacity is greater than or equal to 1000, return the prime number within 11% of the desired capacity
    if (desiredCapacity >= 1000) {
        return desiredCapacity + (desiredCapacity / 100);
    }
    // Otherwise, return the prime number greater than or equal to the desired capacity
    return desiredCapacity;
}

