public final byte[] toByteArray() {
    if (buffers.size() == 1) {
        return buffers.get(0);
    }
    int totalLength = 0;
    for (byte[] buffer : buffers) {
        totalLength += buffer.length;
    }
    byte[] allBytes = new byte[totalLength];
    int offset = 0;
    for (byte[] buffer : buffers) {
        System.arraycopy(buffer, 0, allBytes, offset, buffer.length);
        offset += buffer.length;
    }
    return allBytes;
}

public final byte[] toByteArray() {
    // Create a new byte array with the total size of all the buffers
    byte[] bytes = new byte[bufferSize];

    // Iterate over the buffers and copy their contents into the byte array
    for (int i = 0; i < buffers.length; i++) {
        byte[] buffer = buffers[i].toByteArray();
        System.arraycopy(buffer, 0, bytes, bufferOffset, buffer.length);
        bufferOffset += buffer.length;
    }

    return bytes;
}

public final byte[] toByteArray() {
    if (bufferList.size() == 1) {
        return bufferList.get(0);
    }
    byte[] output = new byte[getTotalSize()];
    int pos = 0;
    for (ByteBuffer buffer : bufferList) {
        System.arraycopy(buffer.array(), 0, output, pos, buffer.limit() - buffer.position());
        pos += buffer.limit() - buffer.position();
    }
    return output;
}

