public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < str.length(); i++) {
        char ch = str.charAt(i);
        if (ch == '\\') {
            if (i == str.length() - 1) {
                sb.append(ch);
                break;
            } else {
                char nextChar = str.charAt(i + 1);
                if (nextChar == 'n') {
                    sb.append("\n");
                    i++;
                } else if (nextChar == 't') {
                    sb.append("\t");
                    i++;
                } else if (nextChar == 'r') {
                    sb.append("\r");
                    i++;
                } else if (nextChar == 'b') {
                    sb.append("\b");
                    i++;
                } else if (nextChar == 'f') {
                    sb.append("\f");
                    i++;
                } else {
                    sb.append(ch);
                }
            }
        } else {
            sb.append(ch);
        }
    }
    return sb.toString();
}

