public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    StringBuffer sb = new StringBuffer(str.length());
    for (int i = 0; i < str.length(); i++) {
        char ch = str.charAt(i);
        if (ch == '\\') {
            if (i + 1 == str.length()) {
                sb.append('\\');
            } else {
                char nextChar = str.charAt(i + 1);
                switch (nextChar) {
                    case 'n':
                        sb.append('\n');
                        i++;
                        break;
                    case 'r':
                        sb.append('\r');
                        i++;
                        break;
                    case 't':
                        sb.append('\t');
                        i++;
                        break;
                    case 'b':
                        sb.append('\b');
                        i++;
                        break;
                    case 'f':
                        sb.append('\f');
                        i++;
                        break;
                    case 'u':
                        if (i + 5 < str.length()) {
                            String unicodeHex = str.substring(i + 2, i + 6);
                            sb.append((char) Integer.parseInt(unicodeHex, 16));
                            i += 5;
                        } else {
                            sb.append('u');
                        }
                        break;
                    default:
                        sb.append('\\');
                }
            }
        } else {
            sb.append(ch);
        }
    }
    return sb.toString();
}

