private int removeUnusedNodes(Category root) {
    if (root == null) {
        return 0;
    }

    int removedCount = 0;
    Stack<Category> nodesToVisit = new Stack<>();
    nodesToVisit.add(root);

    while (!nodesToVisit.isEmpty()) {
        Category currentNode = nodesToVisit.pop();
        if (currentNode.getActive()) {
            nodesToVisit.addAll(currentNode.getChildren());
        } else {
            currentNode.setParent(null);
            removedCount++;
        }
    }

    return removedCount;
}

