private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    // initialize a new circulator to the start node
    OuterFaceCirculator circulator = new OuterFaceCirculator(start, dir);

    // iterate through the nodes on the outer face
    while (circulator.get().compareTo(stop) != 0) {
        // check if the current node satisfies the predicate
        if (predicate.test(circulator.get())) {
            // return a circulator to the current node
            return circulator;
        }
        // move the circulator to the next node on the outer face
        circulator.move(dir);
    }

    // return a circulator to the stop node
    return circulator;
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    OuterFaceCirculator circulator = new OuterFaceCirculator(start, stop, dir);
    Node current = start;
    while (current != stop) {
        if (predicate.test(current)) {
            return circulator.increment();
        }
        current = circulator.next();
    }
    return circulator;
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    Node current = start;
    while (true) {
        if (predicate.test(current)) {
            return new OuterFaceCirculator(current, stop, dir);
        }
        current = current.next;
        if (current == start) {
            break;
        }
    }
    return new OuterFaceCirculator(stop, start, -dir);
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    // Initialize a new circulator to the start node
    OuterFaceCirculator circulator = new OuterFaceCirculator(start);

    // Traverse the graph in the specified direction
    while (circulator.hasNext() && !predicate.test(circulator.next())) {
        circulator.next();
    }

    // If a node satisfies the predicate, return it
    if (predicate.test(circulator.current())) {
        return circulator;
    }

    // If we reached the stop node, return it
    if (circulator.current() == stop) {
        return circulator;
    }

    // If we did not find a node that satisfies the predicate, return the start node
    return new OuterFaceCirculator(start);
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    // Get the outer face circulator for the start node
    OuterFaceCirculator circ = new OuterFaceCirculator(start, dir);

    // Iterate over the nodes on the outer face until we find the one that satisfies the predicate
    while (circ.hasNext()) {
        Node node = circ.next();
        if (predicate.test(node)) {
            return circ;
        }
    }

    // If we didn't find a node that satisfies the predicate, return a circulator to the stop node
    return new OuterFaceCirculator(stop, dir);
}

