    // Check if byteArrayValue is null
    if (byteArrayValue == null) {
        // Put nullbytes into this byte vector
        for (int i = 0; i < byteLength; i++) {
            this.data[this.length++] = 0;
        }
        return this;
    }

    // Check if byteOffset is valid
    if (byteOffset < 0 || byteOffset >= byteArrayValue.length) {
        throw new IndexOutOfBoundsException("byteOffset out of bounds: " + byteOffset);
    }

    // Check if byteLength is valid
    if (byteLength < 0 || byteLength > byteArrayValue.length - byteOffset) {
        throw new IndexOutOfBoundsException("byteLength out of bounds: " + byteLength);
    }

    // Put the byte array into this byte vector
    for (int i = 0; i < byteLength; i++) {
        this.data[this.length++] = byteArrayValue[byteOffset + i];
    }

    return this;
}

