        for (int i = byteOffset; i < byteOffset + byteLength; i++) {
            super.append(null);
        }
    } else {
        // If not null, put the actual bytes into the byte vector
        for (int i = byteOffset; i < byteOffset + byteLength; i++) {
            super.append(byteArrayValue[i]);
        }
    }
    return this;
}

