    for (Entity entity : entities) {
        if (entity.getName().equals(modelName)) {
            if (!isShardingKeyContinuous(entity)) {
                throw new IllegalStateException("Sharding key indices must be continuous for entity " + modelName);
            }
        }
    }
}

private static boolean isShardingKeyContinuous(Entity entity) {
    int lastShardingKeyIndex = -1;
    for (ShardingKey shardingKey : entity.getShardingKeys()) {
        if (shardingKey.getIndex() != lastShardingKeyIndex + 1) {
            return false;
        }
        lastShardingKeyIndex = shardingKey.getIndex();
    }
    return true;
}

