public byte readByte() throws IOException {
    // Check if there is more data in the buffer
    if (buffer.position() < buffer.limit()) {
        // If there is more data in the buffer, return the next byte
        return buffer.get();
    } else {
        // If there is no more data in the buffer, fill the buffer and return the next byte
        fillBuffer();
        return buffer.get();
    }
}

