protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    GraphPath<V,E> path = new GraphPath<V,E>();
    Set<E> visitedEdges = new HashSet<E>();
    for (E edge : tour) {
        if (edge == null) {
            continue;
        }
        if (visitedEdges.contains(edge)) {
            continue;
        }
        visitedEdges.add(edge);
        path.addEdge(edge);
    }
    return path;
}

