int addConstantNameAndType(String name, String descriptor){
    // Check if the constant pool already contains an entry with the given name and descriptor
    for (int i = 0; i < constantPool.size(); i++) {
        ConstantNameAndType entry = constantPool.get(i);
        if (entry.getName().equals(name) && entry.getDescriptor().equals(descriptor)){
            return entry;
        }
    }

    // create a new entry with the given name and descriptor
    ConstantNameAndType entry = new ConstantNameAndType();
    entry.setName(name);
    entry.setDescriptor(descriptor);
    constantPool.add(entry);
    return entry;

}

public Symbol addConstantNameAndType(final String name, final String descriptor) {
    if (constantPool.contains(name, descriptor)) {
        return constantPool.get(name, descriptor);
    }

    Symbol symbol = new Symbol(name, descriptor);
    constantPool.put(symbol);
    return symbol;
}

public int addConstantNameAndType(final String name, final String descriptor) {
    // Check if the constant pool already contains a similar item
    for (int i = 0; i < constant_pool.size(); i++) {
        Symbol symbol = constant_pool.get(i);
        if (symbol.getName().equals(name) && symbol.getDescriptor().equals(descriptor)) {
            return symbol.getIndex();
        }
    }

    // If not, create a new constant and add it to the constant pool
    ConstantNameAndTypeInfo constant = ConstantNameAndTypeInfo.of(name, descriptor);
    constant_pool.add(constant);
    return constant.getIndex();
}

int addConstantNameAndType(string name, string descriptor)
{
    // Try to find a symbol with the same name and descriptor in the constant pool
    Symbol symbol = null;
    for (Symbol s : constantPool) {
        if (s.getName().equals(name) && s.getDescriptor().equals(descriptor)) {
            symbol = s;
            break;
        }
    }

    // If no symbol was found, add a new one
    if (symbol == null) {
        symbol = new Symbol(name, descriptor);
        constantPool.add(symbol);
    }

    return symbol;
}

int addConstantNameAndType(final String name, final String descriptor) {
    // Check if constant pool already contains a similar item
    for (Symbol symbol : constantPool) {
        if (symbol.getName().equals(name) && symbol.getDescriptor().equals(descriptor)) {
            return symbol; // Return existing item
        }
    }
    // Constant pool doesn't contain a similar item, create a new one
    Symbol newSymbol = new Symbol(name, descriptor);
    constantPool.add(newSymbol);
    return newSymbol;
}

private String unescapeId(String input){
    return input.replaceAll("\\\\"+ "(.)", "$1");
}

private String unescapeId(String input) {
    // Create a new string builder with the same size as the input string
    StringBuilder output = new StringBuilder(input.length());

    // Iterate over the input string and replace any escaped characters with their unescaped counterparts
    for (int i = 0; i < input.length(); i++) {
        char currentChar = input.charAt(i);
        if (currentChar == '\\') {
            // The current character is a backslash, so we need to check the next character
            char nextChar = input.charAt(i + 1);
            if (nextChar == 'u') {
                // The next character is 'u', so we need to unescape the Unicode code point
                int codePoint = Integer.decode("0x" + input.substring(i + 2, i + 6));
                output.appendCodePoint(codePoint);
                i += 5;
            } else if (nextChar == 'x') {
                // The next character is 'x', so we need to unescape the hexadecimal code point
                int codePoint = Integer.decode("0x" + input.substring(i + 2, i + 4));
                output.appendCodePoint(codePoint);
                i += 3;
            } else {
                // The current character is not a backslash or 'u' or 'x', so we can just append it as is
                output.append(currentChar);
            }
        } else {
            // The current character is not a backslash, so we can just append it as is
            output.append(currentChar);
        }
    }

    // Return the unescaped output
    return output.toString();
}

private String unescapeId(String input) {
    // Unescape a string DOT identifier
    // Replace all '\' in the input string with ''
    return input.replaceAll("\\\\", "");
}

private String unescapeId(String input) {
    // Replace any escaped single quotes with single quotes
    input = input.replaceAll("''", "'");
    // Replace any escaped double quotes with double quotes
    input = input.replaceAll("\"\"", "\"");
    // Remove any opening and closing single quotes
    if (input.startsWith("'") && input.endsWith("'")) {
        input = input.substring(1, input.length() - 1);
    }
    // Remove any opening and closing double quotes
    if (input.startsWith("\"") && input.endsWith("\"")) {
        input = input.substring(1, input.length() - 1);
    }
    return input;
}

