    Set<Integer> zeroBucket = bucketsByLabel.get(0);
    zeroBucket.addAll(minLabelBucket);
    minLabelBucket.clear();

    // Update labels of vertices in 0 bucket
    for (Integer vertex : zeroBucket) {
        labels.set(vertex, 0);
    }
}

private void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
    Set<Integer> minBucket = bucketsByLabel.get(minLabel);
    Set<Integer> zeroBucket = bucketsByLabel.get(0);

    for (Integer vertex : minBucket) {
        labels.set(vertex, 0);
        zeroBucket.add(vertex);
    }

    bucketsByLabel.set(minLabel, new HashSet<Integer>());
}

public void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
    // Move all vertices from the bucket with label minLabel to the bucket with label 0
    Set<Integer> verticesToMove = bucketsByLabel.get(minLabel);
    Set<Integer> destBucket = bucketsByLabel.get(0);
    for (Integer vertex : verticesToMove) {
        destBucket.add(vertex);
        labels.set(vertex, 0);
    }
    bucketsByLabel.set(minLabel, new HashSet<>());
}

