@Override
    public Class findClass(String className) throws ClassNotFoundException {
        // Check if the class is already loaded
        Class<?> clazz = this.findLoadedClass(className);
        if (clazz != null) {
            return clazz;
        }

        // Load the class from the file system
        try {
            clazz = this.findClassInFiles(className);
        } catch (IOException e) {
            throw new ClassNotFoundException(className, e);
        }

        if (clazz != null) {
            return clazz;
        }

        // Load the class from the parent class loader
        try {
            clazz = this.findClassInParent(className);
        } catch (ClassNotFoundException e) {
            throw new ClassNotFoundException(className, e);
        }

        if (clazz != null) {
            return clazz;
        }

        // Class not found
        throw new ClassNotFoundException(className);
    }

private Class findClass(final String className) throws ClassNotFoundException {
    Objects.requireNonNull(className);
    try {
        // try to load the class from the current classloader
        return Class.forName(className, false, Thread.currentThread().getContextClassLoader());
    } catch (ClassNotFoundException ex) {
        // if the class is not found, try to load it from the system classloader
        return Class.forName(className, false, ClassLoader.getSystemClassLoader());
    }
}

