  }
  ListNodeImpl<E> previous = findPreviousNode(node);
  if (previous != null) {
    previous.next = node.next;
  } else { // node is the head
    head = node.next;
  }
  if (node.next != null) {
    node.next.previous = previous;
  } else { // node is the tail
    tail = previous;
  }
  size -= 1;
  return true;
}

public boolean unlink(ListNodeImpl<E> node) throws NullPointerException, ClassCastException {
    ListNodeImpl<E> curr = this.head;

    if (node == null || this.head == null) {
        throw new NullPointerException("Node cannot be null");
    }

    if (node.getElement() == null) {
        throw new ClassCastException("Node value cannot be null");
    }

    while (curr.next != null) {
        if (curr.next.getElement().equals(node.getElement())) {
            curr.next = curr.next.next;
            return true;
        }
        curr = curr.next;
    }

    return false;
}

private boolean unlink(ListNodeImpl<E> node) {
    if (node == null) {
        return false;
    }

    ListNodeImpl<E> prev = null;
    ListNodeImpl<E> curr = this.head;
    while (curr != null && curr != node) {
        prev = curr;
        curr = curr.next;
    }

    if (curr == null) {
        return false;
    }

    if (prev == null) {
        this.head = curr.next;
    } else {
        prev.next = curr.next;
    }

    this.size--;
    return true;
}

