        }
        for(char terminator : terminators){
            if(currentChar == terminator){
                break;
            }
        }
        token.append((char)currentChar);
        readChar();
    }
    return token.toString();
}

private String parseToken(final char[] terminators) {
    // Initialize the token
    String token = "";

    // Read characters until a terminator is found
    while (true) {
        // Read the next character
        char c = readChar();

        // Check if the character is a terminator
        for (int i = 0; i < terminators.length; i++) {
            if (c == terminators[i]) {
                // If it is a terminator, break out of the loop
                break;
            }
        }

        // Add the character to the token
        token += c;
    }

    // Return the token
    return token;
}

private String parseToken(final char[] terminators) {
    StringBuilder token = new StringBuilder();
    for (int i = 0; i < terminators.length; i++) {
        token.append(terminators[i]);
    }
    String result = token.toString();
    return result;
}

private String parseToken(final char[] terminators) {
    // Initialize an empty token and a boolean value to track if the end of the token has been reached
    String token = "";
    boolean endOfToken = false;

    // Iterate through the input string
    for (int i = 0; i < input.length(); i++) {
        // Check if the current character is a terminator
        for (int j = 0; j < terminators.length; j++) {
            // If the current character is a terminator, set the endOfToken flag to true and break the inner loop
            if (input.charAt(i) == terminators[j]) {
                endOfToken = true;
                break;
            }
        }

        // If the endOfToken flag is true, break the outer loop
        if (endOfToken) {
            break;
        }

        // Otherwise, add the current character to the token
        token += input.charAt(i);
    }

    // Return the token
    return token;
}

