public static final <V>void reverse(V[] arr, int from, int to) {
    if (arr == null || arr.length == 0 || from < 0 || to < 0 || from >= arr.length || to >= arr.length) {
        return;
    }

    int mid = (from + to) / 2;
    for (int i = from; i <= mid; i++) {
        int mirrorIndex = to - (i - from);
        V temp = arr[i];
        arr[i] = arr[mirrorIndex];
        arr[mirrorIndex] = temp;
    }
}

