public static Meteor lookup(HttpServletRequest r) {
    // check if the meteor is already cached
    Meteor meteor = (Meteor) r.getAttribute("meteor");
    if (meteor != null) {
        return meteor;
    }

    // create a new meteor
    meteor = new Meteor();

    // set the meteor's information
    meteor.setName(r.getParameter("name"));
    meteor.setSize(Float.parseFloat(r.getParameter("size")));
    meteor.setDiameter(Float.parseFloat(r.getParameter("diameter")));
    meteor.setHeight(Float.parseFloat(r.getParameter("height")));
    meteor.setMass(Float.parseFloat(r.getParameter("mass")));
    meteor.setDensity(Float.parseFloat(r.getParameter("density")));

    // cache the meteor in the request
    r.setAttribute("meteor", meteor);

    return meteor;
}

