    // Sort the keys in ascending order
    Collections.sort(keys);

    // Initialize the lower bounds list with the first key
    List<Integer> lowerBounds = new ArrayList<>();
    lowerBounds.add(keys.get(0));

    // Iterate over the remaining keys and update the lower bounds
    for (int i = 1; i < keys.size(); i++) {
      int key = keys.get(i);
      int lowerBound = lowerBounds.get(i - 1);

      // If the current key is greater than or equal to the lower bound,
      // update the lower bound with the current key
      if (key >= lowerBound) {
        lowerBounds.add(key);
      } else {
        // Otherwise, update the lower bound with the previous key
        lowerBounds.add(lowerBounds.get(i - 1));
      }
    }

    return lowerBounds;
