private void pop(final String descriptor) {
    int numTypes = descriptor.length();
    for (int i = 0; i < numTypes; i++) {
        char type = descriptor.charAt(i);
        switch (type) {
            case 'L':
                popObject();
                break;
            case '[':
                popArray();
                break;
            case 'I':
                popInt();
                break;
            case 'J':
                popLong();
                break;
            case 'F':
                popFloat();
                break;
            case 'D':
                popDouble();
                break;
            default:
                throw new IllegalArgumentException("Invalid type descriptor: " + descriptor);
        }
    }
}

