    int endIndex = descriptor.indexOf(")");

    // Iterate over the argument types in the descriptor
    for (int i = startIndex; i < endIndex; i++) {
        // Get the current argument type
        String argumentType = descriptor.substring(i, i + 1);

        // Add the argument type to the list
