// Loop through each key in the input list
for (int i = 0; i < keys.size(); i++) {

// If the current key is equal to the last key in the list, set the upper bound to be the last key
if (i == keys.size() - 1) {
upperBounds.set(i, keys.get(i));
}

// Otherwise, find the next key in the list that is greater than the current key
else {
int nextKey = keys.get(i + 1);
if (nextKey > keys.get(i)) {
upperBounds.set(i, nextKey);
} else {
upperBounds.set(i, keys.get(i));
