        int upperBound = i == keys.size() - 1 ? Integer.MAX_VALUE : keys.get(i + 1);
        for (int j = lowerBound; j <= upperBound; j++) {
            if (j > key) {
                upperBounds.set(j, j);
                break;
            }
        }
    }
