    for (String component : relativePathComponents) {
        if (!component.matches("[a-zA-Z0-9_-]+")) {
            throw new IllegalArgumentException("The relative path contains invalid components");
        }
    }

    // Calculate the final path
    StringBuilder finalPath = new StringBuilder();
    for (int i = 0; i < pathComponents.length; i++) {
        if (i > 0) {
            finalPath.append("/");
        }
        finalPath.append(pathComponents[i]);
    }

    // Add the relative path components to the final path
    for (int i = 0; i < relativePathComponents.length; i++) {
        if (i > 0) {
            finalPath.append("/");
        }
        finalPath.append(relativePathComponents[i]);
    }

    return finalPath.toString();
}

