    if (reachedEOF()) {
        return 0;
    }
    int tag = readRawVarint32();
    if (tag == 0) {
        // If we actually read zero, it's not a valid tag.
        throw InvalidProtocolBufferException.malformedVarint();
    }
    return tag;
}

public int readTag() throws IOException {
        if (EOF) {
            return 0;
        }
        int tag = input.read();
        if (tag == EOF) {
            return 0;
        }
        int fieldNumber = tag & TAG_FIELD_NUMBER_MASK;
        int wireType = tag & TAG_WIRE_TYPE_MASK;
        input.mark(1);
        int nextByte = input.read();
        if (nextByte == EOF) {
            throw new IOException("Truncated message.");
        }
        if ((nextByte & TAG_TYPE_MASK) != wireType) {
            throw new IOException("Tag had invalid wire type.");
        }
        int size = (nextByte & TAG_SIZE_MASK) >> TAG_SIZE_SHIFT;
        if (size == 0) {
            throw new IOException("Tag had zero size.");
        }
        input.reset();
        data.setActualByteLength(size);
        data.readFrom(input);
        logRead(size, fieldNumber);
        return fieldNumber;
    }

