    }
    if (byteValue2 < 0 || byteValue2 > 127) {
        throw new IllegalArgumentException("byteValue2 out of range");
    }
    int capacity = data.length;
    if (size + 2 > capacity) {
        capacity *= 2;
        if (capacity < 0) {
            capacity = Integer.MAX_VALUE;
        }
        data = Arrays.copyOf(data, capacity);
