private static boolean isInTimeRange(long startTime, long endTime, List<ProfileAnalyzeTimeRange> timeRanges) {
    for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
        if (startTime >= timeRange.getStartTime() && endTime <= timeRange.getEndTime()) {
