public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    // create a new instance of the thread snapshot parser
    ThreadSnapshotParser parser = new ThreadSnapshotParser();
    // set the file to parse
    parser.setFile(file);
    // parse the file
    List<ThreadSnapshot> snapshots = parser.parse();
    // filter the snapshots based on the specified time range
    List<ThreadSnapshot> filteredSnapshots = new ArrayList<>();
    for (ThreadSnapshot snapshot : snapshots) {
        long snapshotTime = snapshot.getTimeStamp();
        for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
            if (timeRange.contains(snapshotTime)) {
                filteredSnapshots.add(snapshot);
                break;
            }
        }
    }
    return filteredSnapshots;
}
